css:
.rgsbsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #2b2433;
    background: linear-gradient(180deg, #f6f1e7 0%, #efe7d6 100%);
    border-radius: 16px;
}

.rgsbsim-container * {
    box-sizing: border-box;
}

.rgsbsim-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #2a1a3e 0%, #3b2150 50%, #6e1d36 100%);
    color: #f7efe0;
    border-radius: 14px;
    margin-bottom: 20px;
    border: 1px solid #4a2c5e;
    box-shadow: 0 14px 36px rgba(40, 20, 55, 0.35);
}

.rgsbsim-header h1 {
    margin: 10px 0 12px;
    font-family: Georgia, 'Times New Roman', serif;
    font-size: 2.4rem;
    font-weight: 800;
    letter-spacing: -0.4px;
    color: #f3d27e;
}

.rgsbsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #f3d27e;
    background: rgba(243, 210, 126, 0.12);
    border: 1px solid rgba(243, 210, 126, 0.40);
    padding: 5px 14px;
    border-radius: 999px;
}

.rgsbsim-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 1rem;
    line-height: 1.6;
    color: #ecd9e1;
}

.rgsbsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #6e5a4f;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.rgsbsim-period-counter #currentDay,
.rgsbsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #6e1d36;
}

.rgsbsim-round-name {
    background: rgba(110, 29, 54, 0.10);
    color: #6e1d36;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.rgsbsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #8a5a12;
    background: rgba(243, 178, 32, 0.16);
    border: 1px solid rgba(180, 120, 20, 0.35);
    padding: 4px 12px;
    border-radius: 999px;
}

.rgsbsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 14px;
}

.rgsbsim-status-card {
    background: #fffdf8;
    border-radius: 12px;
    padding: 16px 16px 14px;
    border: 1px solid #e3d6bf;
    box-shadow: 0 6px 16px rgba(70, 45, 30, 0.10);
    border-top: 5px solid #3b2150;
}

.rgsbsim-card-accred { border-top-color: #6e1d36; }
.rgsbsim-card-aol { border-top-color: #2f6f5e; }
.rgsbsim-card-faculty { border-top-color: #4a2c8a; }
.rgsbsim-card-surplus { border-top-color: #b9851a; }

.rgsbsim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #7a6a5c;
}

.rgsbsim-value {
    font-size: 2.6rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #2b2433;
    font-variant-numeric: tabular-nums;
}

.rgsbsim-card-accred .rgsbsim-value { color: #6e1d36; }
.rgsbsim-card-aol .rgsbsim-value { color: #2f6f5e; }
.rgsbsim-card-faculty .rgsbsim-value { color: #4a2c8a; }
.rgsbsim-card-surplus .rgsbsim-value { color: #9a6f12; }

.rgsbsim-sublabel {
    font-size: 0.76rem;
    color: #8a7a6a;
    line-height: 1.35;
}

.rgsbsim-surplus-negative .rgsbsim-value { color: #c0392b; }
.rgsbsim-surplus-positive .rgsbsim-value { color: #2f6f5e; }

.rgsbsim-accred-high { border-top-color: #2f8f5e; }
.rgsbsim-accred-high .rgsbsim-value { color: #2f8f5e; }
.rgsbsim-accred-low { border-top-color: #c0392b; }
.rgsbsim-accred-low .rgsbsim-value { color: #c0392b; }

.rgsbsim-faculty-low { border-top-color: #c0392b; }
.rgsbsim-faculty-low .rgsbsim-value { color: #c0392b; }

.rgsbsim-meters {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 14px;
    margin-bottom: 18px;
}

.rgsbsim-meter {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #fffdf8;
    border: 1px solid #e3d6bf;
    border-left: 4px solid #b9851a;
    border-radius: 10px;
    padding: 10px 16px;
    font-weight: 700;
    font-size: 0.9rem;
    color: #5c4d40;
}

.rgsbsim-meter-value {
    font-size: 1.15rem;
    font-weight: 800;
    color: #6e1d36;
    font-variant-numeric: tabular-nums;
}

.rgsbsim-meter-hot .rgsbsim-meter-value { color: #c0392b; }
.rgsbsim-meter-ok .rgsbsim-meter-value { color: #2f8f5e; }

.rgsbsim-briefing {
    display: flex;
    gap: 14px;
    background: #fffdf8;
    border-left: 5px solid #6e1d36;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    border: 1px solid #e3d6bf;
    box-shadow: 0 6px 16px rgba(70, 45, 30, 0.08);
}

.rgsbsim-briefing-icon {
    font-size: 1.9rem;
    line-height: 1;
}

.rgsbsim-briefing-title {
    font-family: Georgia, 'Times New Roman', serif;
    font-weight: 800;
    font-size: 1.12rem;
    color: #3b2150;
    margin-bottom: 6px;
}

.rgsbsim-briefing-text {
    font-size: 0.96rem;
    line-height: 1.6;
    color: #463c4f;
}

.rgsbsim-briefing-text strong { color: #6e1d36; }
.rgsbsim-briefing-text em { color: #9a6f12; font-style: italic; }

.rgsbsim-controls {
    background: #fffdf8;
    border-radius: 12px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e3d6bf;
    box-shadow: 0 6px 16px rgba(70, 45, 30, 0.08);
}

.rgsbsim-controls h3 {
    margin: 0 0 16px;
    font-family: Georgia, 'Times New Roman', serif;
    font-size: 1.18rem;
    font-weight: 800;
    color: #3b2150;
    border-bottom: 2px solid #ecd9c0;
    padding-bottom: 8px;
}

.rgsbsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #4a3f53;
    margin: 16px 0 6px;
}

.rgsbsim-container select,
.rgsbsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #d4c4a6;
    border-radius: 8px;
    font-size: 0.92rem;
    background-color: #fbf6ec;
    color: #2b2433;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.rgsbsim-container select:focus,
.rgsbsim-container input[type="number"]:focus {
    outline: none;
    border-color: #6e1d36;
    box-shadow: 0 0 0 3px rgba(110, 29, 54, 0.14);
}

.rgsbsim-container select option {
    background-color: #fbf6ec;
    color: #2b2433;
}

.rgsbsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #6e1d36;
}

.rgsbsim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #6e5a4f;
    margin-top: 4px;
}

.rgsbsim-range-readout span:last-child {
    color: #6e1d36;
    font-weight: 800;
}

.rgsbsim-hint {
    font-size: 0.81rem;
    color: #8a7a6a;
    margin-top: 5px;
    line-height: 1.45;
    font-style: italic;
}

.rgsbsim-container .btn {
    margin-top: 20px;
    font-weight: 700;
}

.rgsbsim-container .btn-primary {
    background: linear-gradient(135deg, #6e1d36 0%, #9a2a4c 100%);
    border: none;
    color: #f7efe0;
    padding: 11px 28px;
    border-radius: 8px;
    box-shadow: 0 8px 20px rgba(110, 29, 54, 0.35);
}

.rgsbsim-container .btn-primary:hover {
    filter: brightness(1.08);
}

.rgsbsim-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #c4b393;
    color: #7a6a5c;
    background: transparent;
}

.rgsbsim-coach {
    background: linear-gradient(135deg, #2a1a3e 0%, #3b2150 100%);
    color: #ecd9e1;
    border: 1px solid #4a2c5e;
    border-radius: 12px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 20px rgba(40, 20, 55, 0.25);
}

.rgsbsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #f3d27e;
    margin-bottom: 8px;
}

.rgsbsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.6;
}

.rgsbsim-coach-body strong { color: #f3d27e; }
.rgsbsim-coach-body em { color: #f0b8c8; font-style: italic; }

.rgsbsim-history,
.rgsbsim-chart {
    background: #fffdf8;
    border-radius: 12px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e3d6bf;
    box-shadow: 0 6px 16px rgba(70, 45, 30, 0.08);
}

.rgsbsim-history h3,
.rgsbsim-chart h3 {
    margin: 0 0 14px;
    font-family: Georgia, 'Times New Roman', serif;
    font-size: 1.1rem;
    font-weight: 800;
    color: #3b2150;
}

.rgsbsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #463c4f;
}

.rgsbsim-container table#usfHistoryTable th {
    background: #f3ecdc;
    color: #6e1d36;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e0d0b3;
}

.rgsbsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #ece2cf;
    color: #54485f;
}

.rgsbsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #fbf6ec;
}

.rgsbsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .rgsbsim-container {
        padding: 14px;
    }
    .rgsbsim-header h1 {
        font-size: 1.8rem;
    }
    .rgsbsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .rgsbsim-value {
        font-size: 2.1rem;
    }
    .rgsbsim-meters {
        grid-template-columns: 1fr;
    }
    .rgsbsim-clock {
        margin-left: 0;
    }
    .rgsbsim-period-counter {
        font-size: 0.88rem;
    }
    .rgsbsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* === rgsbsim-cm: completion debrief (appended, adapter 1.1.0) === */
.rgsbsim-cm { max-width: 640px; margin: 0 auto; font-family: inherit; }
.rgsbsim-cm-head { display: flex; align-items: baseline; gap: 14px; flex-wrap: wrap; margin-bottom: 14px; }
.rgsbsim-cm-score { font-size: 3rem; font-weight: 800; line-height: 1; color: #0b3d5c; }
.rgsbsim-cm-max { font-size: 1.1rem; font-weight: 600; color: #6b7a86; margin-left: 2px; }
.rgsbsim-cm-grade { font-size: 1.25rem; font-weight: 700; color: #123; }
.rgsbsim-cm-badges { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 16px; }
.rgsbsim-cm-badge { font-size: .82rem; font-weight: 600; padding: 4px 10px; border-radius: 999px; border: 1px solid transparent; }
.rgsbsim-cm-ok { background: #e4f5ea; color: #1c7a43; border-color: #b7e2c7; }
.rgsbsim-cm-no { background: #fdecec; color: #b23b3b; border-color: #f3c4c4; }
.rgsbsim-cm-kpis { display: grid; grid-template-columns: repeat(auto-fit, minmax(96px, 1fr)); gap: 10px; margin-bottom: 16px; }
.rgsbsim-cm-kpi { background: #f4f7f9; border: 1px solid #e1e8ed; border-radius: 8px; padding: 10px 8px; text-align: center; }
.rgsbsim-cm-kpi-v { font-size: 1.2rem; font-weight: 700; color: #0b3d5c; }
.rgsbsim-cm-kpi-l { font-size: .74rem; color: #6b7a86; margin-top: 3px; }
.rgsbsim-cm-insights { margin: 0; padding-left: 20px; }
.rgsbsim-cm-insights li { margin: 5px 0; line-height: 1.4; }

