(function() {
    'use strict';

    class RgsbAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Quality at Scale`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (RGSB, EUR).
            this.BASELINE_SURPLUS = 8.6;     // EUR M operating surplus (9% of 96M)
            this.PROGRAM_CONTRIB = 2.6;      // EUR M contribution of the DAX custom program
            this.SENIOR_POOL = 22;           // over-loaded senior research professors
            this.EXEC_STAFFING_NEED = 8;     // seniors the custom program needs
            this.START_LOAD = 1.34;          // avg senior-faculty load (x of 100% norm)
            this.START_BELOW = 2;            // programs below SA/PA threshold (of 12)

            // Concept truths.
            this.TRUE_DIAGNOSIS = `both`;
            this.TRUE_PRIORITY = `cascade`;
            this.TRUE_PROGRAM = `rescope`;
            this.TRUE_AOL = `proportionate`;
            this.TRUE_GOVERNANCE = `policy`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    accred: 30,              // accreditation readiness (AACSB/EQUIS, SA/PA coverage)
                    aol: 15,                 // quality / assurance-of-learning system
                    faculty: 35,             // faculty sustainability (load below ceiling, attrition risk)
                    surplus: this.BASELINE_SURPLUS,  // EUR M operating surplus
                    load: this.START_LOAD,   // avg senior-faculty load
                    below: this.START_BELOW, // programs below SA/PA threshold
                    overReliedAdjunct: false,
                    overDrew: false,
                    logoChased: false,
                    accredHistory: [30],
                    aolHistory: [15],
                    facultyHistory: [35],
                    surplusHistory: [this.BASELINE_SURPLUS],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are a deliberately middling / wrong-leaning mix —
                // a blind click-through must not auto-win.
                state.decisions = {
                    diagnosis: `staffing`,
                    priority: `hire`,
                    honesty: 40,
                    seniorExec: 14,
                    adjunct: 1.5,
                    substitute: `ip_only`,
                    research: 40,
                    program: `full`,
                    aolStandard: `none`,
                    ceiling: 1.5,
                    governance: `adhoc`,
                    brief: `rosy`,
                    contingency: `ignore`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const dg = document.getElementById(`diagnosisInput`);
                const pr = document.getElementById(`priorityInput`);
                const ho = document.getElementById(`honestyInput`);
                if (dg) decisions.diagnosis = dg.value;
                if (pr) decisions.priority = pr.value;
                if (ho) decisions.honesty = parseInt(ho.value, 10);
                if (!Number.isFinite(decisions.honesty) || decisions.honesty < 0 || decisions.honesty > 100) {
                    warn(`warn_honesty_range`); return false;
                }
            } else if (round === 2) {
                const se = document.getElementById(`seniorExecInput`);
                const ad = document.getElementById(`adjunctInput`);
                const su = document.getElementById(`substituteInput`);
                const re = document.getElementById(`researchInput`);
                if (se) decisions.seniorExec = parseInt(se.value, 10);
                if (ad) decisions.adjunct = parseFloat(ad.value);
                if (su) decisions.substitute = su.value;
                if (re) decisions.research = parseInt(re.value, 10);
                if (!Number.isFinite(decisions.seniorExec) || decisions.seniorExec < 0 || decisions.seniorExec > this.SENIOR_POOL) {
                    warn(`warn_seniorexec_range`); return false;
                }
                if (!Number.isFinite(decisions.adjunct) || decisions.adjunct < 0) {
                    warn(`warn_adjunct_value`); return false;
                }
                if (!Number.isFinite(decisions.research) || decisions.research < 0 || decisions.research > 100) {
                    warn(`warn_research_range`); return false;
                }
            } else if (round === 3) {
                const pg = document.getElementById(`programInput`);
                const as = document.getElementById(`aolStandardInput`);
                const ce = document.getElementById(`ceilingInput`);
                if (pg) decisions.program = pg.value;
                if (as) decisions.aolStandard = as.value;
                if (ce) decisions.ceiling = parseFloat(ce.value);
                if (!Number.isFinite(decisions.ceiling) || decisions.ceiling < 1 || decisions.ceiling > 2) {
                    warn(`warn_ceiling_range`); return false;
                }
            } else if (round === 4) {
                const gv = document.getElementById(`governanceInput`);
                const br = document.getElementById(`briefInput`);
                const co = document.getElementById(`contingencyInput`);
                const cv = document.getElementById(`convictionInput`);
                if (gv) decisions.governance = gv.value;
                if (br) decisions.brief = br.value;
                if (co) decisions.contingency = co.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let accredDelta = 0, aolDelta = 0, facultyDelta = 0, surplusDelta = 0;
            let loadDelta = 0, belowDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose: separate the staffing problem from the governance problem (Common Error 2).
                switch (d.diagnosis) {
                    case `both`: accredDelta += 6; aolDelta += 10; facultyDelta += 4; coachKey = `coach_r1_both`; break;
                    case `staffing`: aolDelta -= 4; accredDelta += 2; coachKey = `coach_r1_staffing`; break;
                    case `margin`: accredDelta -= 4; aolDelta -= 4; facultyDelta -= 3; coachKey = `coach_r1_margin`; break;
                    case `reporting`: aolDelta -= 6; accredDelta -= 3; coachKey = `coach_r1_reporting`; break;
                }

                // Name the real cascade exposure (EQUIS conditions -> AACSB -> public).
                switch (d.priority) {
                    case `cascade`: accredDelta += 8; aolDelta += 4; if (d.diagnosis === `both`) coachKey = `coach_r1_sharp`; break;
                    case `hire`: accredDelta += 1; break;
                    case `logo`: accredDelta -= 3; ds.logoChased = true; break;
                    case `nps`: accredDelta -= 6; aolDelta -= 4; coachKey = `coach_r1_nps`; break;
                }

                // Honestly counting exec days reveals the real over-utilization.
                if (d.honesty >= 80) { facultyDelta += 8; aolDelta += 4; accredDelta += 2; }
                else if (d.honesty <= 30) { facultyDelta -= 6; accredDelta -= 3; coachKey = `coach_r1_undercount`; }
                else { facultyDelta += 2; }

                summaryKey = (d.diagnosis === `both` && d.priority === `cascade` && d.honesty >= 70) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Allocate faculty under the binding senior-capacity envelope (Common Errors 1 & 4).
                const execSeniors = d.seniorExec;       // seniors pushed into exec (0..22)
                const adj = d.adjunct;                   // EUR M adjunct budget

                // Degree programs need senior coverage to hold threshold. Pushing too many
                // seniors into exec re-opens program shortfalls; pulling too few starves exec.
                const SUSTAINABLE_EXEC = 8;              // ~the custom-program need; above this drains degree
                const execOver = Math.max(0, execSeniors - SUSTAINABLE_EXEC);
                const execUnder = Math.max(0, 6 - execSeniors);

                // Each senior beyond the sustainable line drags a degree program toward threshold.
                belowDelta += Math.floor(execOver / 4);  // every 4 over-pushed seniors trips a program
                accredDelta -= execOver * 1.4;
                loadDelta += execOver * 0.02;            // over-pushed seniors run hotter
                if (execUnder > 0) { surplusDelta -= 0.3; } // exec growth starved costs margin
                else { surplusDelta += 0.4; }

                // Adjunct budget: moderate use frees research time & covers gaps; heavy use
                // pushes core courses below threshold (Common Error 4: adjunct over-reliance).
                if (adj >= 3) {
                    ds.overReliedAdjunct = true; belowDelta += 1; accredDelta -= 5; surplusDelta += 0.3; coachKey = `coach_r2_adjunct`;
                } else if (adj >= 1.5) {
                    accredDelta += 4; facultyDelta += 4; surplusDelta -= 0.2;
                } else {
                    accredDelta -= 2; facultyDelta -= 2; surplusDelta += 0.1;
                }

                // How the degree gaps are covered. A governed mix (seniors held in degree
                // coverage, targeted PA practitioners, an SA pipeline) actually RESTORES the
                // two sub-threshold programs — but only if seniors weren't over-pushed to exec.
                switch (d.substitute) {
                    case `mix`:
                        accredDelta += 8; aolDelta += 3; facultyDelta += 4; coachKey = `coach_r2_mix`;
                        belowDelta -= (execOver === 0) ? 2 : 1;   // clears the SA/PA shortfall when capacity is protected
                        break;
                    case `ip_only`: belowDelta += 1; accredDelta -= 6; surplusDelta += 0.2; if (coachKey === `coach_default`) coachKey = `coach_r2_iponly`; break;
                    case `hire_only`: belowDelta -= 1; accredDelta -= 4; coachKey = `coach_r2_hireonly`; break;
                }

                // Protect tenure-track research time (feeds SA classification & sustainability).
                if (d.research >= 60) { facultyDelta += 6; accredDelta += 3; surplusDelta -= 0.2; }
                else if (d.research <= 25) { facultyDelta -= 5; accredDelta -= 3; loadDelta += 0.03; coachKey = `coach_r2_research`; }

                summaryKey = (execSeniors <= 10 && d.substitute === `mix` && adj < 3 && d.research >= 50) ? `sum_r2_good` :
                             (ds.overReliedAdjunct ? `sum_r2_adjunct` : `sum_r2_weak`);
            } else if (round === 3) {
                // The 6,2 Mio. € program + the AoL standard + the load ceiling (Common Errors 1 & 3).
                switch (d.program) {
                    case `rescope`:
                        surplusDelta += this.PROGRAM_CONTRIB * 0.62;   // capture most of the contribution
                        accredDelta += 5; aolDelta += 8; facultyDelta += 3; coachKey = `coach_r3_rescope`; break;
                    case `full`:
                        surplusDelta += this.PROGRAM_CONTRIB;          // book the full contribution
                        facultyDelta -= 14; loadDelta += 0.18; belowDelta += 1; accredDelta -= 8;
                        ds.overDrew = true; ds.logoChased = true; coachKey = `coach_r3_full`; break;
                    case `decline`:
                        surplusDelta -= 0.4;                            // forgo contribution, protect people
                        facultyDelta += 6; accredDelta += 2; coachKey = `coach_r3_decline`; break;
                }

                // Minimum AoL standard for the exec portfolio (proportionate vs heavy vs none).
                switch (d.aolStandard) {
                    case `proportionate`: aolDelta += 16; accredDelta += 8; surplusDelta -= 0.3; coachKey = `coach_r3_aolprop`; break;
                    case `heavy`: aolDelta += 8; accredDelta += 4; surplusDelta -= 2.3; coachKey = `coach_r3_aolheavy`; break;
                    case `none`: aolDelta -= 10; accredDelta -= 6; surplusDelta += 0.2; coachKey = `coach_r3_aolnone`; break;
                }

                // The sustainable load ceiling — governs attrition risk.
                if (d.ceiling <= 1.3) { facultyDelta += 12; accredDelta += 4; surplusDelta -= 0.3; loadDelta -= 0.10; }
                else if (d.ceiling <= 1.5) { facultyDelta += 3; loadDelta -= 0.04; }
                else { facultyDelta -= 8; loadDelta += 0.06; ds.overDrew = true; if (coachKey === `coach_default`) coachKey = `coach_r3_ceiling`; }

                summaryKey = (d.program === `rescope` && d.aolStandard === `proportionate` && d.ceiling <= 1.4) ? `sum_r3_good` :
                             (d.program === `full` ? `sum_r3_full` : (d.aolStandard === `heavy` ? `sum_r3_heavy` : `sum_r3_weak`));
            } else if (round === 4) {
                // Defend the brief + the governance rule (Common Error 5 & sustainability).
                switch (d.governance) {
                    case `policy`: accredDelta += 10; aolDelta += 8; facultyDelta += 6; coachKey = `coach_r4_policy`; break;
                    case `margin`: accredDelta -= 6; facultyDelta -= 4; coachKey = `coach_r4_margin`; break;
                    case `adhoc`: accredDelta -= 3; aolDelta -= 3; coachKey = `coach_r4_adhoc`; break;
                }

                switch (d.brief) {
                    case `evidenced`: accredDelta += 12; aolDelta += 6; if (d.governance === `policy`) coachKey = `coach_r4_defended`; break;
                    case `rosy`: accredDelta -= 6; facultyDelta -= 3; coachKey = `coach_r4_rosy`; break;
                    case `defensive`: accredDelta -= 8; aolDelta -= 4; coachKey = `coach_r4_defensive`; break;
                }

                switch (d.contingency) {
                    case `absorb`: facultyDelta += 10; accredDelta += 6; surplusDelta -= 0.3; break;
                    case `hope`: facultyDelta -= 2; break;
                    case `ignore`: facultyDelta -= 8; accredDelta -= 5; coachKey = `coach_r4_contingency`; break;
                }

                if (d.conviction >= 60) { accredDelta += 4; aolDelta += 3; }
                else if (d.conviction <= 25) { accredDelta -= 4; aolDelta -= 3; }

                summaryKey = (d.governance === `policy` && d.brief === `evidenced` && d.contingency === `absorb`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Apply load & threshold meters (load: x of norm; below: 0..12 programs).
            ds.load = Math.max(0.9, Math.round((ds.load + loadDelta) * 100) / 100);
            ds.below = Math.max(0, Math.min(12, ds.below + belowDelta));

            // Apply KPI deltas, clamped (0-100; surplus is EUR M, can go negative).
            ds.accred = Math.max(0, Math.min(100, Math.round(ds.accred + accredDelta)));
            ds.aol = Math.max(0, Math.min(100, Math.round(ds.aol + aolDelta)));
            ds.faculty = Math.max(0, Math.min(100, Math.round(ds.faculty + facultyDelta)));
            ds.surplus = Math.round((ds.surplus + surplusDelta) * 10) / 10;

            ds.accredHistory.push(ds.accred);
            ds.aolHistory.push(ds.aol);
            ds.facultyHistory.push(ds.faculty);
            ds.surplusHistory.push(ds.surplus);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = this._composite(ds);

            return {
                period: state.currentPeriod,
                accred: ds.accred,
                accredDelta: Math.round(accredDelta),
                aol: ds.aol,
                aolDelta: Math.round(aolDelta),
                faculty: ds.faculty,
                facultyDelta: Math.round(facultyDelta),
                surplus: ds.surplus,
                surplusDelta: Math.round(surplusDelta * 10) / 10,
                load: ds.load,
                below: ds.below,
                overReliedAdjunct: ds.overReliedAdjunct,
                overDrew: ds.overDrew,
                logoChased: ds.logoChased,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtMoney(v) {
            // German EUR notation everywhere: "8,6 Mio. €" (comma decimal, symbol after).
            const sign = v < 0 ? `-` : ``;
            const abs = Math.abs(v);
            return `${sign}${abs.toFixed(1).replace(`.`, `,`)} Mio. €`;
        }

        _fmtLoad(v) {
            return `${Number(v).toFixed(2).replace(`.`, `,`)}×`;
        }

