            uiManager.bind(`loadDisplay`, `domainState.load`, (v) => {
                const m = document.querySelectorAll(`.rgsbsim-meter`)[0];
                if (m) {
                    m.classList.toggle(`rgsbsim-meter-hot`, Number(v) >= 1.4);
                    m.classList.toggle(`rgsbsim-meter-ok`, Number(v) <= 1.25);
                }
                return self._fmtLoad(Number(v));
            });
            uiManager.bind(`thresholdDisplay`, `domainState.below`, (v) => {
                const m = document.querySelectorAll(`.rgsbsim-meter`)[1];
                if (m) {
