        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.accredHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                rgsbChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.accredHistory },
                        { data: ds.aolHistory },
                        { data: ds.facultyHistory }
                    ]
                }
            };
        }

        // _composite(ds): single source of truth for the 0-100 score (v1.0.0 formula, verbatim).
        _composite(ds) {
            const accred = Math.round(ds.accred);
            const aol = Math.round(ds.aol);
            const faculty = Math.round(ds.faculty);
            const surplus = ds.surplus;
            const surplusScore = Math.max(-20, Math.min(20, surplus * 2));
            return Math.round(accred * 0.32 + aol * 0.26 + faculty * 0.26 + (surplusScore + 20) * 0.40);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const accred = Math.round(ds.accred);
            const aol = Math.round(ds.aol);
            const faculty = Math.round(ds.faculty);
            const surplus = ds.surplus;

            // Composite via _composite(ds) — single source of truth (v1.0.0 formula).
            const composite = this._composite(ds);

            const accredited = accred >= 60 && ds.below === 0;
            const evidenced = aol >= 60;
            const sustainable = faculty >= 55 && ds.load <= 1.4;
            const solvent = surplus >= 0;
            const overdrawn = ds.overDrew || ds.load >= 1.55 || faculty <= 30;

            let performanceKey = `grade_conditions`;
            if (accredited && evidenced && sustainable && solvent && composite >= 75) performanceKey = `grade_secured`;
            else if (accredited && evidenced && solvent) performanceKey = `grade_held`;
            else if (overdrawn) performanceKey = `grade_burnout`;
            else if (ds.below >= 2) performanceKey = `grade_below`;
            else if (composite >= 55) performanceKey = `grade_mixed`;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (accredited && evidenced && sustainable && solvent) insights.push(window.mySimulation.t(`insight_secured`));
            else if (overdrawn) insights.push(window.mySimulation.t(`insight_burnout`));
            else if (ds.below >= 2) insights.push(window.mySimulation.t(`insight_belowthreshold`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (ds.logoChased && faculty < 45) insights.push(window.mySimulation.t(`insight_logo`));
            if (ds.overReliedAdjunct) insights.push(window.mySimulation.t(`insight_adjunct`));
            if (aol < 40) insights.push(window.mySimulation.t(`insight_noaol`));
            if (surplus < 4) insights.push(window.mySimulation.t(`insight_margin`));
            if (accredited && evidenced && sustainable) insights.push(window.mySimulation.t(`insight_system`));

            return {
                accred: accred,
                aol: aol,
                faculty: faculty,
                surplus: surplus,
                accredited: accredited,
                evidenced: evidenced,
                sustainable: sustainable,
                solvent: solvent,
                overdrawn: overdrawn,
                composite: composite,
                performance: performance,
                performanceKey: performanceKey,
                met: (accredited && evidenced && sustainable && solvent),
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const s = summary || {};
            const t = (k) => window.mySimulation.t(k);
            const esc = (x) => String(x == null ? `` : x).replace(/[&<>]/g, (c) => ({ '&': `&amp;`, '<': `&lt;`, '>': `&gt;` }[c]));
            const score = (s.composite != null) ? s.composite : 0;
            const grade = s.performance || t(s.performanceKey || `grade_conditions`);
            const badge = (ok, okKey, noKey) => `<span class="rgsbsim-cm-badge ${ok ? `rgsbsim-cm-ok` : `rgsbsim-cm-no`}">${esc(t(ok ? okKey : noKey))}</span>`;
            const kpi = (label, val) => `<div class="rgsbsim-cm-kpi"><div class="rgsbsim-cm-kpi-v">${esc(val)}</div><div class="rgsbsim-cm-kpi-l">${esc(label)}</div></div>`;
            const insights = (s.insights || []).map((i) => `<li>${esc(i)}</li>`).join(``);
            let badges = badge(s.accredited === true, `cm_badge_accredited`, `cm_badge_notaccredited`)
                       + badge(s.evidenced === true, `cm_badge_evidenced`, `cm_badge_noevidence`)
                       + badge(s.sustainable === true, `cm_badge_sustainable`, `cm_badge_strained`)
                       + badge(s.solvent === true, `cm_badge_solvent`, `cm_badge_deficit`);
            if (s.overdrawn) badges += `<span class="rgsbsim-cm-badge rgsbsim-cm-no">${esc(t(`cm_badge_overdrawn`))}</span>`;
            const surplus = (s.surplus != null) ? this._fmtMoney(Number(s.surplus)) : `\u2014`;
            return `<div class="rgsbsim-cm">`
                + `<div class="rgsbsim-cm-head"><div class="rgsbsim-cm-score">${score}<span class="rgsbsim-cm-max">/100</span></div>`
                + `<div class="rgsbsim-cm-grade">${esc(grade)}</div></div>`
                + `<div class="rgsbsim-cm-badges">${badges}</div>`
                + `<div class="rgsbsim-cm-kpis">`
                + kpi(t(`cm_kpi_accred`), (s.accred != null ? s.accred : `\u2014`))
                + kpi(t(`cm_kpi_aol`), (s.aol != null ? s.aol : `\u2014`))
                + kpi(t(`cm_kpi_faculty`), (s.faculty != null ? s.faculty : `\u2014`))
                + kpi(t(`cm_kpi_surplus`), surplus)
                + kpi(t(`cm_kpi_index`), score)
                + `</div>`
                + (insights ? `<ul class="rgsbsim-cm-insights">${insights}</ul>` : ``)
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.overDrew || ds.load >= 1.55) return window.mySimulation.t(`hint_overdraw`);
            if (ds.below >= 2) return window.mySimulation.t(`hint_below`);
            if (ds.overReliedAdjunct) return window.mySimulation.t(`hint_adjunct`);
            if (state.currentPeriod >= 3 && ds.aol < 40) return window.mySimulation.t(`hint_aol`);
            if (ds.surplus < 4 && state.currentPeriod >= 3) return window.mySimulation.t(`hint_margin`);
            if (ds.accred >= 65 && ds.aol >= 60 && ds.faculty >= 55) return window.mySimulation.t(`hint_strong`);
            return null;
        }

